#include <bits/stdc++.h>
using namespace std;
bool isVowel(char c) { return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'; }
int main() {
    string s;
    int k;
    cin >> s >> k;
    int count = 0;
    for (int i = 0; i < k; i++) count += isVowel(s[i]);
    int best = count;
    for (int i = k; i < (int)s.size(); i++) {
        count += isVowel(s[i]) - isVowel(s[i - k]);
        best = max(best, count);
    }
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
