int main() {
    string s, p;
    cin >> s >> p;
    int m = p.size();
    array<int, 26> need{}, have{};
    for (char c : p) need[c - 'a']++;
    int count = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        have[s[i] - 'a']++;
        if (i >= m) have[s[i - m] - 'a']--;
        if (i >= m - 1 && have == need) count++;
    }
    cout << count << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    unordered_map<char, int> last;  // character -> index where it was last seen
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        auto it = last.find(s[right]);
        if (it != last.end() && it->second >= left) left = it->second + 1;
        last[s[right]] = right;
        best = max(best, right - left + 1);
    }
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    int left = 0, best = 0;
    long long total = 0;
    for (int right = 0; right < n; right++) {
        total += a[right];
        while (total > k) total -= a[left++];
        best = max(best, right - left + 1);
    }
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    int k;
    cin >> s >> k;
    array<int, 26> count{};
    int distinct = 0, left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        if (count[s[right] - 'a']++ == 0) distinct++;
        while (distinct > k) {
            if (--count[s[left] - 'a'] == 0) distinct--;
            left++;
        }
        best = max(best, right - left + 1);
    }
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    int left = 0, best = n + 1;
    long long total = 0;
    for (int right = 0; right < n; right++) {
        total += a[right];
        while (total >= target) {
            best = min(best, right - left + 1);
            total -= a[left++];
        }
    }
    cout << (best <= n ? best : 0) << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    long long product = 1, count = 0;
    int left = 0;
    for (int right = 0; right < n; right++) {
        product *= a[right];
        while (product >= k && left <= right) product /= a[left++];
        count += right - left + 1;
    }
    cout << count << "\n";
    return 0;
}

